callback_with_context.context_function_id:
#hide the layout at various circumstances#
( ritual_context = PlayersFaction.RitualContextForKey("wh3_dlc29_woc_glottking_convert_settlement_to_garden") ) =>
{
 Do( ritual_context.RitualInteractionContext.ClearTarget, ritual_context.RitualInteractionContext.EnableTargetting(false), Component("dlc29_chs_planting_garden_of_nurgle_ritual_panel").Trash )
}

(localized = Loc("wh3_dlc29_gardens_of_nurgle_ritual_panel_corruption_requirement"),
 total = TargettingContext.CurrentTargetContext.ProvinceContext.PooledResourceContext("wh3_main_corruption_nurgle").Total,
 required = Settlements.GetGardenOfNurgleRequiredCorruption) =>
{
 GetIfElse(
  total >= required,
  Format(localized, total, required),
  Format(localized.Replace("%d/%d", "[[col:red]]%d[[/col]]/%d"), total, required)
 )
}
